package com.bookreads.storage

import androidx.datastore.core.DataStoreFactory
import androidx.datastore.core.okio.OkioStorage
import kotlinx.coroutines.flow.first
import okio.FileSystem

class PrefServiceDataStore(private val pathProvider: PrefPathProvider) : LocalStorageService {

    private val dataStore = DataStoreFactory.create(
        storage = OkioStorage(
            fileSystem = FileSystem.SYSTEM,
            serializer = AppPreferencesSerializer,
            producePath = { pathProvider.get() },
        ),
    )

    override suspend fun getUsername(): String? = dataStore.data.first().username

    override suspend fun saveUsername(username: String) {
        dataStore.updateData { it.copy(username = username) }
    }

    override suspend fun getActiveSession(): SessionData? = dataStore.data.first().activeSession

    override suspend fun saveActiveSession(session: SessionData) {
        dataStore.updateData { it.copy(activeSession = session) }
    }

    override suspend fun clearActiveSession() {
        dataStore.updateData { it.copy(activeSession = null) }
    }
}
```

