package com.bookreads.storage

import kotlinx.serialization.json.Json

class PrefServiceLocalStorage : LocalStorageService {

    override suspend fun getUsername(): String? = getLocalStorageItem("bookreads_username")

    override suspend fun saveUsername(username: String) {
        setLocalStorageItem("bookreads_username", username)
    }

    override suspend fun getActiveSession(): SessionData? {
        val json = getLocalStorageItem("bookreads_session") ?: return null
        return try {
            Json.decodeFromString<SessionData>(json)
        } catch (e: Exception) {
            null
        }
    }

    override suspend fun saveActiveSession(session: SessionData) {
        setLocalStorageItem("bookreads_session", Json.encodeToString(SessionData.serializer(), session))
    }

    override suspend fun clearActiveSession() {
        removeLocalStorageItem("bookreads_session")
    }
}
```

